internal data class PersonalizationSection(
    val key: String,
    val label: String,
    val keywords: List<String>,
    val title: String = label,
    val summary: String = "",
)

internal data class PersonalizationControl(val key: String, val title: String, val aliases: List<String>)

/** One declaration owns the label, reset policy, storage key and search destination of a field. */
internal data class PersonalizationField(
    val key: String,
    val label: String,
    val category: String,
    val storageKey: Preferences.Key<*>,
    val additionalStorageKeys: List<Preferences.Key<*>> = emptyList(),
    val resettable: Boolean = true,
    val searchSection: String? = category,
    val entryPoint: String,
    val preservationReason: String? = null,
    val compared: Boolean = true,
    val control: PersonalizationControl? = null,
)

