internal fun personalizationCategoryTitle(key: String): String =
    personalizationSections.firstOrNull { it.key == key }?.title ?: when (key) {
        "maintenance" -> "帮助与维护"
        "statistics" -> "统计页设置"
        "community" -> "社区页设置"
        "tier" -> "排行榜设置"
        "character" -> "角色页设置"
        "library" -> "收藏页设置"
        "discovery" -> "发现与来源设置"
        "calendar" -> "日历偏好"
        "editor" -> "编辑偏好"
        "branding" -> "品牌与启动"
        else -> "其他个性化设置"
    }
